CURRENT_TEST = None


class PacketError(RuntimeError):
    def __init__(self, code):
        self.code = code
        super().__init__(code)


def require(condition, code):
    if not condition:
        raise PacketError(code)


def sha256(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def validate_payload():
    require(sha256(PAYLOAD_TEXT + "\n") == PAYLOAD_SHA256, "payload_digest_mismatch")
    payload = json.loads(PAYLOAD_TEXT)
    require(type(payload["schema_version"]) is int and payload["schema_version"] == 1,
            "unsupported_payload_schema")
    require(sha256(payload["corrected_candidate_patch"]) ==
            payload["corrected_candidate_sha256"], "candidate_digest_mismatch")
    seen = set()
    for item in payload["source_files"]:
        path = PurePosixPath(item["path"])
        require(not path.is_absolute() and ".." not in path.parts and
                item["path"] == str(path) and item["path"] not in seen,
                "unsafe_or_duplicate_source_path")
        require(sha256(item["content"]) == item["sha256"], "source_digest_mismatch")
        if path.suffix == ".py":
            ast.parse(item["content"], filename=item["path"])
        seen.add(item["path"])
    for test in payload["tests"]:
        require(test["path"] in seen and type(test["expected_tests"]) is int and
                test["expected_tests"] > 0 and type(test["run_optimized"]) is bool,
                "invalid_test_plan")
    require(sum(t["expected_tests"] for t in payload["tests"]) == 72,
            "normal_collection_plan_mismatch")
    require(sum(t["expected_tests"] for t in payload["tests"] if t["run_optimized"]) == 14,
            "optimized_collection_plan_mismatch")
    require(payload["total_timeout_seconds"] == 1020, "time_bound_mismatch")
    return payload


